void ScriptSession::removeItem(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return;auto state=items_.at(handle);if(state->removing)return;state->removing=true;if(alive(state->holder,NativeKind::Unit))dropItem(state->holder,handle);if(!alive(handle,NativeKind::Item))return;if(alive(state->holder,NativeKind::Unit))for(auto& slot:units_.at(state->holder)->inventory)if(slot==handle)slot=0;auto holder=state->holder;items_.erase(handle);++fogRevision_;destroy(runtime_.handle("item",handle),NativeKind::Item);if(alive(holder,NativeKind::Unit))refreshEquipment(*units_.at(holder));}
void ScriptSession::consumeItem(std::uint32_t handle) {if(purchasedItems_.contains(handle))consumedPurchases_.insert(handle);else removeItem(handle);}
