bool ScriptSession::itemTargetsItems(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return false;for(auto id:itemActiveAbilities(items_.at(handle)->type))if(definitions().field(id,"AbilityData","code")=="ANcl" && spellInfo(id,1).allowed.contains("item"))return true;return false;}
bool ScriptSession::itemTargetsTrees(std::uint32_t handle) {if(!alive(handle,NativeKind::Item))return false;for(auto id:itemActiveAbilities(items_.at(handle)->type))if((definitions().field(id,"AbilityData","code")=="Aprg" || definitions().field(id,"AbilityData","code")=="Aeat") && spellInfo(id,1).allowed.contains("tree"))return true;return false;}
double ScriptSession::itemCooldown(std::uint32_t unitId,std::uint32_t itemId) {if(!alive(unitId,NativeKind::Unit) || !alive(itemId,NativeKind::Item))return 0;auto u=units_.at(unitId);auto item=items_.at(itemId);auto entries=itemActiveAbilities(item->type);if(entries.empty())return 0;auto group=definitions().field(item->type,"ItemData","cooldownID",ObjectData::name(entries.front()));auto found=u->itemCooldowns.find(group);return found==u->itemCooldowns.end()?0:std::max(0.,found->second-simulationTime_);}
bool ScriptSession::itemNeedsPoint(std::uint32_t id){if(!alive(id,NativeKind::Item))return false;for(auto ability:itemActiveAbilities(items_.at(id)->type)){if(auto c=consumableInfo(ability);c && c->kind==ConsumableKind::Dispel && definitions().number(items_.at(id)->type,"ItemData","powerup")==0)return true;auto code=definitions().field(ability,"AbilityData","code");if(code=="ANcl"){auto target=spellInfo(ability,1).targeting;if(target==SpellTargeting::Point || target==SpellTargeting::Either)return true;}if(code=="AHbz" || code=="ANto" || code=="AIfa" || code=="AEbl" || code=="Ahwd" || code=="Aeye" || code=="Asta" || code=="Aclf" || code=="AIta" || code=="AUds" || code=="AHmt" || code=="AItp" || code=="AIrt" || code=="ANsi" || code=="AIbl" || code=="AUin" || code=="AIpm" || code=="AImo" || code=="Ablp")return true;}return false;}
bool ScriptSession::itemAutoTargetsBase(std::uint32_t id){if(!alive(id,NativeKind::Item))return false;for(auto ability:itemActiveAbilities(items_.at(id)->type)){auto code=definitions().field(ability,"AbilityData","code");if(code=="AHmt" || code=="AItp")return true;}return false;}
bool ScriptSession::itemAllowsUnitAndPoint(std::uint32_t id){if(!alive(id,NativeKind::Item))return false;if(itemAutoTargetsBase(id))return true;for(auto ability:itemActiveAbilities(items_.at(id)->type))if(definitions().field(ability,"AbilityData","code")=="ANcl" && spellInfo(ability,1).targeting==SpellTargeting::Either)return true;return false;}
bool ScriptSession::useItem(std::uint32_t unit,std::uint32_t item,std::uint32_t target){return useItemImpl(unit,item,target,{});}
bool ScriptSession::useItemAt(std::uint32_t unit,std::uint32_t item,WorldPoint point){return useItemImpl(unit,item,0,point);}
